import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0:
        print("Min: " + str(-2147483648))
        print("Max: " + str(2147483647))
        return

    numbers = list(map(int, data[1:n+1]))

    min_val = 2147483647
    max_val = -2147483648

    for num in numbers:
        if num < min_val:
            min_val = num
        if num > max_val:
            max_val = num

    print("Min: " + str(min_val))
    print("Max: " + str(max_val))

    for num in numbers:
        if num < 0:
            sign = "Negative"
        elif num == 0:
            sign = "Zero"
        else:
            sign = "Positive"
        print(str(num) + ": " + sign)

if __name__ == "__main__":
    main()
